#!/usr/bin/env bash
set -e;R="$(cd "$(dirname "$0")/.."&&pwd)";command -v python3 >/dev/null&&python3 -m py_compile "$R/python/app.py";command -v node >/dev/null&&node --check "$R/node/app.js";command -v go >/dev/null&&go build -o "$R/go/network-api" "$R/go/main.go";command -v cargo >/dev/null&&cargo check --manifest-path "$R/rust/Cargo.toml";command -v javac >/dev/null&&{ mkdir -p "$R/java/out";javac "$R/java/Main.java" -d "$R/java/out";};command -v dotnet >/dev/null&&dotnet build "$R/csharp/BizXtreme.NetworkApi.csproj";command -v c++ >/dev/null&&c++ -std=c++17 "$R/cpp/main.cpp" -o "$R/cpp/network-api";command -v dart >/dev/null&&dart analyze "$R/dart/bin/main.dart";command -v kotlinc >/dev/null&&kotlinc "$R/kotlin/Main.kt" -d "$R/kotlin/network-api.jar";command -v swiftc >/dev/null&&swiftc "$R/swift/main.swift" -o "$R/swift/network-api";command -v php >/dev/null&&php -l "$R/php/main.php";command -v ruby >/dev/null&&ruby -c "$R/ruby/main.rb";echo 'NetworkUnified build checks complete for available toolchains.'
